// State parameters
  localparam IDLE  = 3'b000;
  localparam S_1   = 3'b001;
  localparam S_11  = 3'b010;
  localparam S_110 = 3'b011;
  localparam DONE  = 3'b100;

  // State registers
  reg [2:0] current_state, next_state;

  // Synchronous state transition logic
  always @(posedge clk) begin
    if (reset)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  // Combinational next state logic
  always @(*) begin
    case (current_state)
      IDLE: 
        if (data)
          next_state = S_1;
        else
          next_state = IDLE;
      S_1: 
        if (data)
          next_state = S_11;
        else
          next_state = IDLE;
      S_11: 
        if (data)
          next_state = S_11; // Overlapping part of "111" is "11"
        else
          next_state = S_110;
      S_110: 
        if (data)
          next_state = DONE;
        else
          next_state = IDLE;
      DONE: 
        next_state = DONE; // Remain in DONE state
      default: 
        next_state = IDLE;
    endcase
  end

  // Moore output logic
  assign start_shifting = (current_state == DONE);

endmodule

